			return dir, nil // lost the race; the winner's tree is equivalent
		}
		return "", fmt.Errorf("publish plugin deps to %q: %w", dir, err)
	}
	fmt.Fprintf(os.Stderr, "opencode: built plugin deps for %s in %s at %s\n", version, elapsed, dir)
	return dir, nil
